import 'package:material_ui/material_ui.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../theme/theme.dart';
import 'loopy_icons.g.dart';

/// A hand-drawn loopy icon (paths generated by scripts/build_brand.py).
class LoopyIcon extends StatelessWidget {
  const LoopyIcon(this.name, {super.key, this.size = 26, this.color, this.stroke = 2.4});

  final String name;
  final double size;
  final Color? color;
  final double stroke;

  @override
  Widget build(BuildContext context) {
    final c = color ?? IconTheme.of(context).color ?? TColors.ink;
    final hex = '#${(c.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';
    final paths = (loopyPaths[name] ?? loopyPaths['ball']!).map((d) => '<path d="$d"/>').join();
    final svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" fill="none" stroke="$hex" '
        'stroke-width="$stroke" stroke-linecap="round" stroke-linejoin="round">$paths</svg>';
    return SvgPicture.string(svg, width: size, height: size);
  }
}

/// The Tracka mark (head, kicking body, ball), in any colour.
class TrackaMark extends StatelessWidget {
  const TrackaMark({super.key, this.size = 28, this.color = TColors.neon});

  final double size;
  final Color color;

  @override
  Widget build(BuildContext context) {
    final hex = '#${(color.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';
    return SvgPicture.string(
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 185 196" fill="$hex">$trackaMarkSvgBody</svg>',
      height: size,
    );
  }
}

/// The app's logo lockup: neon tile with the dark mark, plus the wordmark.
class TrackaLogo extends StatelessWidget {
  const TrackaLogo({super.key, this.size = 34});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Row(mainAxisSize: MainAxisSize.min, children: [
      Container(
        width: size,
        height: size,
        decoration: BoxDecoration(color: TColors.neon, borderRadius: BorderRadius.circular(size * 0.29)),
        alignment: Alignment.center,
        child: TrackaMark(size: size * 0.6, color: TColors.onNeon),
      ),
      const SizedBox(width: 10),
      Text('tracka',
          style: TextStyle(
              fontFamily: TType.display, fontWeight: FontWeight.w700, fontSize: size * 0.68, letterSpacing: -1)),
    ]);
  }
}

/// A score set like a shirt number in motion: tall, tabular, slanted.
class KitNumber extends StatelessWidget {
  const KitNumber(this.value, {super.key, this.size = 96, this.color});

  final int? value;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    return Transform(
      transform: Matrix4.skewX(-0.16),
      child: Text(
        value?.toString() ?? '–',
        style: TextStyle(
          fontFamily: TType.display,
          fontWeight: FontWeight.w700,
          fontSize: size,
          height: 0.86,
          letterSpacing: -size * 0.06,
          color: color,
          fontFeatures: const [FontFeature.tabularFigures()],
        ),
      ),
    );
  }
}

class Eyebrow extends StatelessWidget {
  const Eyebrow(this.text, {super.key, this.color});

  final String text;
  final Color? color;

  @override
  Widget build(BuildContext context) => Text(text.toUpperCase(), style: TType.eyebrow.copyWith(color: color));
}

class Pill extends StatelessWidget {
  const Pill(this.text, {super.key, this.color = TColors.inkSoft, this.background});

  final String text;
  final Color color;
  final Color? background;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: background ?? color.withValues(alpha: 0.14),
        borderRadius: BorderRadius.circular(999),
      ),
      child: Text(text.toUpperCase(),
          style: TextStyle(fontSize: 10.5, fontWeight: FontWeight.w700, letterSpacing: 1.2, color: color)),
    );
  }
}

class ConfidencePill extends StatelessWidget {
  const ConfidencePill(this.confidence, {super.key, this.suffix = ''});

  final String? confidence;
  final String suffix;

  @override
  Widget build(BuildContext context) =>
      Pill('${confidence ?? 'LOW'}$suffix', color: TColors.forConfidence(confidence));
}

/// A rounded bar that grows to [value] (0-100).
class ScoreBar extends StatelessWidget {
  const ScoreBar(this.value, {super.key, this.color = TColors.neon, this.height = 8});

  final num value;
  final Color color;
  final double height;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(999),
      child: Container(
        height: height,
        color: TColors.surface3,
        alignment: Alignment.centerLeft,
        child: TweenAnimationBuilder<double>(
          tween: Tween(begin: 0, end: (value / 100).clamp(0, 1).toDouble()),
          duration: const Duration(milliseconds: 900),
          curve: Curves.easeOutCubic,
          builder: (_, v, __) => FractionallySizedBox(
            widthFactor: v,
            child: Container(decoration: BoxDecoration(color: color, borderRadius: BorderRadius.circular(999))),
          ),
        ),
      ),
    );
  }
}

/// A rounded panel. [neon] makes it the one loud card on a screen.
class TCard extends StatelessWidget {
  const TCard({super.key, required this.child, this.neon = false, this.padding = const EdgeInsets.all(20), this.onTap, this.accent});

  final Widget child;
  final bool neon;
  final EdgeInsets padding;
  final VoidCallback? onTap;
  final String? accent; // a big faint loopy icon tucked into the corner

  @override
  Widget build(BuildContext context) {
    final card = Container(
      decoration: BoxDecoration(
        color: neon ? TColors.neon : TColors.surface,
        borderRadius: BorderRadius.circular(TRadius.lg),
        border: Border.all(color: neon ? TColors.neon : TColors.lineSoft),
      ),
      clipBehavior: Clip.antiAlias,
      child: Stack(children: [
        if (accent != null)
          Positioned(
            right: -18,
            bottom: -22,
            child: Opacity(
              opacity: neon ? 0.14 : 0.10,
              child: LoopyIcon(accent!, size: 140, color: neon ? TColors.onNeon : TColors.neon, stroke: 1.6),
            ),
          ),
        Padding(
          padding: padding,
          child: DefaultTextStyle.merge(
            style: TextStyle(color: neon ? TColors.onNeon : null),
            child: IconTheme.merge(data: IconThemeData(color: neon ? TColors.onNeon : null), child: child),
          ),
        ),
      ]),
    );
    if (onTap == null) return card;
    return Material(
      color: Colors.transparent,
      child: InkWell(onTap: onTap, borderRadius: BorderRadius.circular(TRadius.lg), child: card),
    );
  }
}

/// The skewed dashed neon "tape" under big titles.
class Tape extends StatelessWidget {
  const Tape({super.key, this.width = 150});

  final double width;

  @override
  Widget build(BuildContext context) {
    return Transform(
      transform: Matrix4.skewX(-0.55),
      child: SizedBox(
        width: width,
        height: 9,
        child: Row(children: [
          for (var i = 0; i < (width / 22).floor(); i++) ...[
            Container(width: 13, color: TColors.neon),
            const SizedBox(width: 9),
          ],
        ]),
      ),
    );
  }
}

class EmptyState extends StatelessWidget {
  const EmptyState({super.key, required this.icon, required this.title, required this.message, this.action});

  final String icon;
  final String title;
  final String message;
  final Widget? action;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(32),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          LoopyIcon(icon, size: 72, color: TColors.inkFaint),
          const SizedBox(height: 14),
          Text(title, style: Theme.of(context).textTheme.headlineMedium, textAlign: TextAlign.center),
          const SizedBox(height: 8),
          Text(message, style: const TextStyle(color: TColors.inkSoft), textAlign: TextAlign.center),
          if (action != null) ...[const SizedBox(height: 20), action!],
        ]),
      ),
    );
  }
}

/// A chip that toggles, for positions and clip types.
class ChoiceChipT extends StatelessWidget {
  const ChoiceChipT({super.key, required this.label, required this.selected, required this.onTap});

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
        decoration: BoxDecoration(
          color: selected ? TColors.neon : TColors.surface2,
          borderRadius: BorderRadius.circular(999),
          border: Border.all(color: selected ? TColors.neon : TColors.line),
        ),
        child: Text(label,
            style: TextStyle(
                fontWeight: FontWeight.w700, fontSize: 13, color: selected ? TColors.onNeon : TColors.inkSoft)),
      ),
    );
  }
}

void showSnack(BuildContext context, String message) {
  ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(content: Text(message)));
}
